'use strict';
window.InferenceUI=(()=>{
 const d=window.HERB_DATA,c=window.FORMULA_CORPUS,I=window.InferenceModel;
 const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
 const link=(url,label)=>/^https:\/\//.test(url||'')?`<a class="small-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
 const F=id=>c.formulas.find(f=>f.id===id),E=id=>c.sourceElements.find(e=>e.id===id);
 const pct=x=>Number.isFinite(x)?(x*100).toFixed(1)+'%':'未估計',num=x=>Number.isFinite(x)?x.toFixed(3):'未估計';
 const core=f=>f.ingredientRefs.filter(r=>r.scope!=='auxiliary');
 const coverage=f=>core(f).filter(r=>r.id).length/core(f).length;
 let ctx,active,q='',book='',page=0,chosen=c.formulas[0]?.id,queryId=c.formulas[0]?.id,elementId='',prediction=null,validation=window.INFERENCE_VALIDATION?.familyValidation||null,association=null,model=null,lastQuery=null;
 const getModel=()=>model||(model=I.fit(d,c));
 const elementsByFrequency=()=>c.sourceElements.map(e=>({...e,n:c.formulas.filter(f=>f.sourceElementIds.includes(e.id)).length})).sort((a,b)=>b.n-a.n||a.name.localeCompare(b.name));
 const frequent=elementsByFrequency();elementId=frequent[0]?.id;
 function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function bar(label,value,detail){return `<div class="inference-bar"><span>${esc(label)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,(value||0)*100))}%"></div></div><b>${pct(value)}</b></div>${detail?`<p class="table-note">${esc(detail)}</p>`:''}`}
 function citation(f){const missing=core(f).filter(r=>!r.id);return `<span class="citation-icon" aria-hidden="true">“</span><div><h3>${esc(f.name)} · 擷取原方</h3><blockquote>${esc(f.rawIngredientText)}</blockquote><p>${link(f.sourceURL,f.sourceBook)} · ${esc(f.sourceChapter)}</p><div class="notice">載入時工作台為 ${core(f).filter(r=>r.id).length} 個可映射原名的等權子集，原方共有 ${core(f).length} 個文本元素。${missing.length?'未載入：'+missing.map(r=>esc(r.sourceName)).join('、')+'。':''}份數不還原原方劑量；本草映射未核定現代身份。</div></div>`}
 function stats(){return `<div class="research-stats"><div><b>${c.formulas.length}</b><span>新增來源方記錄・全部待逐條校勘</span></div><div><b>${c.sourceElements.length}</b><span>原名文本元素</span></div><div><b>${c.qaReport.uniqueElementSetCount}</b><span>不同元素集合・仍需核方族</span></div><div><b>${pct(c.qaReport.catalogMappingCoverage)}</b><span>成分引用可精確映射本草目錄</span></div></div>`}
 function downloads(){return `<div class="download-bar"><span>原方、元素矩陣與模型方法</span><a class="button secondary" href="downloads/tcm-research-library.zip" download>下載完整研究包</a><a class="small-link" href="downloads/formulas.csv" download>方劑 CSV</a><a class="small-link" href="downloads/formula-elements.csv" download>元素矩陣 CSV</a><a class="small-link" href="downloads/inference-validation.json" download>分組驗證報告</a></div>`}
 function render(view,context){ctx=context;active=view;if(queryId==='workbench'&&lastQuery?.selection&&(JSON.stringify(lastQuery.selection)!==JSON.stringify(ctx.selection())||lastQuery.sourceFormula?.id!==ctx.origin?.()?.id)){prediction=null;association=null;}const panel=document.querySelector('#view-content');panel.innerHTML=view==='formulas'?formulaHTML():inferenceHTML()}
 function matching(){const term=q.trim().toLocaleLowerCase();return c.formulas.filter(f=>(!book||f.sourceId===book)&&(!term||[f.name,f.rawIndications,...f.ingredientRefs.map(r=>r.sourceName)].join(' ').toLocaleLowerCase().includes(term)))}
 function rows(){const found=matching();page=Math.min(page,Math.max(0,Math.ceil(found.length/20)-1));return `<div class="table-scroll"><table class="research-table"><thead><tr><th>方劑 / 原典</th><th>成分結構</th><th>主治原文</th><th>目錄映射</th></tr></thead><tbody>${found.slice(page*20,(page+1)*20).map(f=>`<tr><td><button class="text-button" data-formula-record="${esc(f.id)}">${esc(f.name)}</button><small>${esc(f.sourceBook)}<br>${esc(f.sourceChapter)}</small>${f.sameNameDifferentComposition?'<span class="review-tag">同名異組成</span>':''}</td><td>${f.ingredientRefs.map(r=>`<span class="tag">${esc(r.sourceName)}</span>`).join('')}</td><td>${esc(f.rawIndications.slice(0,110))}${f.rawIndications.length>110?'…':''}<small>原文聲稱・未作臨床標準答案</small></td><td>${core(f).filter(r=>r.id).length} / ${core(f).length}<small>原名元素均保留</small><button class="text-button" data-infer-record="${esc(f.id)}">反推此方 →</button></td></tr>`).join('')}</tbody></table></div><div class="pager"><span>${found.length} 筆結果・第 ${page+1} / ${Math.max(1,Math.ceil(found.length/20))} 頁</span><button class="button secondary" data-formula-page="-1" ${!page?'disabled':''}>上一頁</button><button class="button secondary" data-formula-page="1" ${(page+1)*20>=found.length?'disabled':''}>下一頁</button></div>`}
 function detail(){const f=F(chosen);if(!f)return '';return `<section class="panel research-panel" id="formula-record-detail"><span class="eyebrow">SOURCE RECORD · ${esc(f.id)}</span><div class="inference-heading"><h2>${esc(f.name)}</h2><span class="review-tag">自動擷取・待逐條核</span></div><p>${link(f.sourceURL,f.sourceBook)} · ${esc(f.sourceChapter)}</p><details><summary>版本與原文定位</summary><p>${esc(f.sourceEdition)}</p><p>方名：Unicode 字符 ${f.nameSpan.start}–${f.nameSpan.end}；成分：${f.ingredientTextSpan.start}–${f.ingredientTextSpan.end}；主治：${f.profileEvidence.map(x=>`${x.evidenceSpan.start}–${x.evidenceSpan.end}`).join('、')}。位置基於封存轉錄，結束位置不含。</p><p>詞族：${esc(f.familyBaseName)}；同名異組成：${f.sameNameDifferentComposition?'是':'未標出'}。分組是字面防洩漏輔助，尚未完成歷史方族譜系。</p></details><div class="inference-two"><div><h3>原方成分・特徵輸入</h3><blockquote class="source-quote">${esc(f.rawIngredientText)}</blockquote><div class="table-scroll"><table class="research-table compact-table"><thead><tr><th>原名元素</th><th>炮製摘記</th><th>二元特徵</th><th>本草目錄映射</th></tr></thead><tbody>${core(f).map(r=>`<tr><td>${esc(r.sourceName)}</td><td>${esc(r.preparation||'未摘記')}</td><td>1</td><td>${r.id?`<button class="text-button" data-detail="${esc(r.id)}">${esc(d.herbs.find(h=>h.id===r.id)?.name||r.id)}</button>`:esc(r.mappingStatus==='ambiguous_text'?'同名多條・待辨':'尚未映射')}</td></tr>`).join('')}</tbody></table></div><p class="rule-note">1 代表此轉錄成分清單出現；0 代表清單未列該原名。可由原文定位的炮製詞另作二元特徵；古籍數量只保留考證，不作模型輸入，也不表示濃度或效力。</p></div><div><h3>獨立主治段落・對照目標</h3><blockquote class="source-quote">${esc(f.rawIndications)}</blockquote><p class="rule-note">主治不放入預測輸入；模型以固定詞典從其他方主治生成銀標籤。這些是歷史表述，尚缺盲法人工標註與現代驗證。</p><div class="research-controls"><button class="button primary" data-infer-record="${esc(f.id)}">分析此方的文獻藥性</button><button class="button secondary" data-stage-record="${esc(f.id)}" ${!core(f).some(r=>r.id)?'disabled':''}>載入可映射子集</button><button class="button secondary" data-export-record="${esc(f.id)}">匯出原方記錄</button></div></div></div></section>`}
 function frequency(){return `<section class="panel research-panel"><h2>成分元素量化</h2><p>每方每原名最多計一次；分母為 ${c.formulas.length} 個來源記錄，相同組成的不同版本仍保留。模型驗證另將同族／同元素集合鎖在同組。</p><div class="table-scroll"><table class="research-table"><thead><tr><th>原名元素</th><th>出現方數</th><th>來源記錄涵蓋</th><th>身份狀態</th></tr></thead><tbody>${frequent.slice(0,15).map(e=>`<tr><td>${esc(e.name)}</td><td>${e.n}</td><td>${pct(e.n/c.formulas.length)}</td><td>${e.catalogHerbId?'文字可映射本草條目':'保留原名・目錄待辨'}<small>現代物種／部位未核定</small></td></tr>`).join('')}</tbody></table></div></section>`}
 function formulaHTML(){return stats()+`<div class="notice">從《傷寒論》《金匱要略》《太平惠民和劑局方》按章節輪選明列成分且有主治段落的記錄，各書最多 100 筆。新增語料與原有 18 個校核基準分開保留；全部新增方待逐條校勘。礦物、動物材料及古名作文本元素保留。</div><section class="panel research-panel"><h2>方劑語料檢索</h2><div class="research-controls"><input class="search" id="formula-corpus-query" aria-label="搜尋方劑語料" placeholder="方名、原名材料或主治原詞" value="${esc(q)}"><select id="formula-corpus-book" aria-label="方劑典籍"><option value="">全部三部來源</option>${c.sources.map(s=>`<option value="${esc(s.id)}" ${s.id===book?'selected':''}>${esc(s.title)} · ${c.formulas.filter(f=>f.sourceId===s.id).length} 筆</option>`).join('')}</select></div><div id="formula-corpus-rows">${rows()}</div></section><div id="formula-detail-container">${detail()}</div>${frequency()}${downloads()}`}
 function queryOptions(){return `<option value="workbench" ${queryId==='workbench'?'selected':''}>目前工作台 · 自選元素</option>${c.formulas.map(f=>`<option value="${esc(f.id)}" ${f.id===queryId?'selected':''}>${esc(f.name)} · ${esc(f.sourceBook)}</option>`).join('')}`}
 function inferenceHTML(){return `<div class="notice">這裡的「藥性」指原文主治詞的組合關聯。由配伍結構推估文獻表述，再觀察各元素的條件關聯；共同成分、方族、編纂習慣都可能造成關聯，不能唯一反推出單味藥的實際功效。</div><section class="panel research-panel"><span class="eyebrow">COMPOSITION → HISTORICAL TEXT</span><h2>選一方，反推文獻主治詞</h2><div class="research-controls"><select id="inference-query" aria-label="反推方劑">${queryOptions()}</select><button class="button primary" id="run-inference">執行反推分析</button><button class="button secondary" id="export-inference" ${!prediction?'disabled':''}>匯出分析與依據</button></div><p class="rule-note">輸入為原名成分有／無與可定位炮製詞。方名、主治、草藥功用標籤與古籍劑量不作輸入；工作台反推目前只採成分有／無；所選炮製分支、實錄克數及溫度、時間尚未納入訓練，改動它們不代表反推分數會改變。炮製與質量的文獻分布請查看工作台或特性量化頁。資料方會排除自身及同名、字面詞族／相同元素集合的連通組。</p><div id="inference-results">${qualityHTML(validation)}${prediction?predictionHTML():'<p class="empty-state">選擇方劑後執行分析，查看支持度、主治詞排序與來源案例。</p>'}</div></section><section class="panel research-panel"><h2>元素與主治詞的關聯</h2><div class="research-controls"><input class="search" id="inference-element-search" aria-label="搜尋反推元素" placeholder="搜尋原名元素"><select id="inference-element" aria-label="選擇反推元素">${elementOptions()}</select><button class="button secondary" id="run-element-association">分析元素關聯</button></div><div id="element-association-results">${association?associationHTML():'<p class="rule-note">查看帶有此元素及未列此元素的方，其原文詞頻差異。支持不足會保留未知。</p>'}</div></section><section class="panel research-panel"><h2>實際分組驗證</h2><p>整個連通方組一起留出，五折輪流以成分推估其他組的主治銀標籤，再與訓練集詞頻基準比較。數據來源及方族字面分組仍可能有偏差；本結果是此批文獻內驗證。</p><button class="button secondary" id="run-inference-validation">${validation?'重新查看分組驗證':'執行五折分組驗證'}</button><div id="inference-validation-results">${validation?validationHTML():'<p class="rule-note">尚未在本頁執行；執行後展示實測值。獨立人工標註及跨來源外部驗證仍未完成。</p>'}</div><details><summary>查看演算法、固定詞典與研究邊界</summary><div id="inference-method-description">${methodHTML()}</div></details></section>${downloads()}`}
 function elementOptions(term=''){return frequent.filter(e=>!term||e.name.includes(term)).map(e=>`<option value="${esc(e.id)}" ${e.id===elementId?'selected':''}>${esc(e.name)} · ${e.n} 方</option>`).join('')}
 function methodHTML(){return `<p>以原名元素二元集合及可定位炮製詞計算詞語關聯，近似案例以元素集合重疊檢索。詞典、平滑、支持門檻及分組規則皆公開。罕見詞、低元素覆蓋或缺乏近似案例時保留未知或拒絕推估。</p><p>${'<a class="small-link" href="downloads/inference-methodology.json" download>下載完整模型方法 ↗</a>'}</p><h3>固定主治詞典</h3>${I.dictionary.map(x=>`<p><strong>${esc(x.label)}</strong><br>${x.terms.map(esc).join('、')}</p>`).join('')}<h3>預先固定的支持門檻</h3><pre class="research-json">${esc(JSON.stringify(I.defaults,null,2))}</pre><p>參數並未依此批留出結果調整。近似方族以同名／字面方族、相同成分、成分相似及共享原文分支構成連通組；這仍是防洩漏代理，並非完整譜系。</p><p>這不是化學合成或人體藥效模擬。現代身份、完整炮製細分、協同機制、毒理與臨床驗證尚未完成。原名不同不自動視作不同物質，原名相同也不自動視作同物。</p>`}
 function qualityHTML(r){if(!r?.performed||!r.metrics)return '';const m=r.metrics,b=r.baselineMetrics;return `<div class="notice ${m.brier>b.brier?'model-caution':''}"><strong>文獻內驗證：${m.brier>b.brier?'平方誤差高於詞頻基準，分數尚不可靠':'仍需獨立人工與外部驗證'}</strong><br>成分模型 Brier ${num(m.brier)}，詞頻基準 ${num(b.brier)}（越低越好）；微平均 F1 ${num(m.microF1)} / 基準 ${num(b.microF1)}。數值是探索性排序，不作可信度或實際藥性結論。</div>`}
 function predictionHTML(){const r=prediction,f=F(queryId);return `<div class="inference-status"><span class="review-tag ${!r.abstained?'reviewed':''}">${esc(r.status)}</span><strong>${esc(f?.name||ctx.name())}</strong></div><div class="profile-summary"><div><span>原名元素可編碼</span><b>${pct(r.textElementCoverage)}</b></div><div><span>本草目錄映射</span><b>${pct(r.catalogMappingCoverage)}</b></div><div><span>有訓練支持的元素</span><b>${pct(r.supportedElementCoverage)}</b></div></div>${r.processingEvidence?`<p class="rule-note">炮製輸入：${esc(r.processingEvidence.status)}。未記錄不當作無炮製。</p>`:''}${r.reasons?.length?`<div class="notice">${r.reasons.map(esc).join('；')}</div>`:''}<div class="inference-two"><div><h3>推估詞排序・非療效概率</h3>${termsHTML(r.terms,r.abstained)}${r.unsupportedTargets?.length?`<details><summary>${r.unsupportedTargets.length} 個支持不足的主題</summary><p>${r.unsupportedTargets.map(t=>esc(t.label)+'：'+esc(t.reason)).join('<br>')}</p></details>`:''}<p class="rule-note">排序數值只由其他方原文詞與成分關聯計算。未預測某詞不代表不存在該方義。</p>${f?`<details><summary>對照此方獨立主治原文</summary><blockquote class="source-quote">${esc(f.rawIndications)}</blockquote>${link(f.sourceURL,'此方原文')}</details>`:''}</div><div><h3>近似訓練案例・保留出處</h3>${nearestHTML(r.nearestCases)}<p class="rule-note">近似組成不能解作同效或可替代；展示案例已排除資料查詢方的整個分組。</p></div></div><details><summary>訓練子集、排除組與限制</summary><pre class="research-json">${esc(JSON.stringify(r.trainingSubset,null,2))}</pre><p>${(r.limitations||[]).map(esc).join('；')}</p></details>`}
 function termsHTML(terms,abstained){if(abstained||!terms?.length)return '<p class="empty-state">支持不足，保留未知。可查看來源案例與元素關聯。</p>';return terms.map(t=>`<div class="term-result">${bar(t.label,t.associationScore,'訓練詞頻基準 '+pct(t.baselineScore)+'；門檻 '+pct(t.threshold)+'；'+(t.predicted?'達到詞典命中推估門檻':'未達門檻'))}<details><summary>支持頻數與元素貢獻</summary><p>${t.support.ruleHit} 方命中此詞、${t.support.ruleNotHit} 方未命中；訓練 ${t.support.groups} 組。</p><pre class="research-json">${esc(JSON.stringify(t.contributions,null,2))}</pre></details></div>`).join('')}
 function nearestHTML(cases){if(!cases?.length)return '<p class="rule-note">沒有足夠的近似訓練案例。</p>';return cases.slice(0,5).map(x=>{const f=F(x.formulaId||x.id);return `<article class="nearby-case"><strong>${esc(f?.name||x.name)}</strong> <span class="review-tag">成分重疊 ${pct(x.similarity??x.jaccard)}</span><p>${esc(f?.rawIndications||x.rawIndications||'')}</p>${link(f?.sourceURL||x.sourceURL,f?.sourceBook||x.sourceBook||'原文來源')}</article>`}).join('')}
 function associationHTML(){const r=association;return `<p>${esc(E(elementId)?.name)}：${esc(r.status||'描述性關聯')}；${esc(r.corpusRecords)} 個可用方、${esc(r.corpusGroups)} 個分組。帶此元素 ${esc(typeof r.support==='number'?r.support:JSON.stringify(r.support))} 方，跨 ${esc(r.elementPresentGroups??'待計')} 組；未列此元素跨 ${esc(r.elementAbsentGroups??'待計')} 組。</p>${r.associations?.length?`<div class="table-scroll"><table class="research-table"><thead><tr><th>主治原詞主題</th><th>含此元素且有詞</th><th>含此元素且未錄詞</th><th>未列元素且有詞</th><th>兩者未錄</th><th>log lift</th></tr></thead><tbody>${r.associations.map(a=>`<tr><td>${esc(a.label||a.id)}</td><td>${esc(a.n11??a.table?.n11??'—')}</td><td>${esc(a.n10??a.table?.n10??'—')}</td><td>${esc(a.n01??a.table?.n01??'—')}</td><td>${esc(a.n00??a.table?.n00??'—')}</td><td>${num(a.logLift)}<small>${a.supported?'平滑條件命中 '+pct(a.conditionalRuleHit):'支持不足・保留未知'}</small><details><summary>來源分層 / 原文案例</summary><p>${a.sourceStrata.map(x=>esc(x.sourceBook)+'：'+x.elementPresent+' 方有元素、其中 '+x.ruleHitAmongPresent+' 方命中詞').join('<br>')}</p>${a.examples.map(x=>link(x.sourceURL,x.name)).join(' · ')}</details></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-state">此元素或主題支持不足，未作關聯排序。</p>'}<details><summary>共同成分與不可辨識性</summary><pre class="research-json">${esc(JSON.stringify(r.identifiability?.identicalOccurrenceColumns||[],null,2))}</pre><p>${(r.identifiability?.notes||r.limitations||[]).map(esc).join('；')}</p></details>`}
 function validationHTML(){const r=validation;return `<p><span class="review-tag ${r.performed?'reviewed':''}">${esc(r.status)}</span> ${r.performed?'已實際計算分組留出結果':'未能執行驗證'}</p><div id="validation-metric-table">${metricHTML(r)}</div><p class="rule-note">可評估查詢 ${r.coverage?.scoredQueryRecords??0} / ${r.coverage?.testRecords??0} 方（${pct(r.coverage?.queryCoverage)}）；可評估詞判斷涵蓋 ${pct(r.coverage?.labelDecisionCoverage)}。其餘拒絕推估，不計為正確。</p><details><summary>每折、支持度與完整結果</summary><pre class="research-json">${esc(JSON.stringify(r,null,2))}</pre></details>`}
 function metricHTML(r){if(!r.metrics)return '<p class="rule-note">樣本不足，未報告估計。</p>';const m=r.metrics,b=r.baselineMetrics||{};return `<div class="table-scroll"><table class="research-table"><thead><tr><th>實測指標</th><th>成分模型</th><th>訓練詞頻基準</th></tr></thead><tbody>${['microPrecision','microRecall','microF1','macroF1','brier'].filter(k=>k in m&&k in b).map(k=>`<tr><td>${esc(({microF1:'微平均 F1',macroF1:'宏平均 F1',microPrecision:'微平均精確率',microRecall:'微平均召回率',brier:'Brier 平方誤差'})[k]||k)}</td><td>${num(m[k])}</td><td>${num(b[k])}</td></tr>`).join('')}</tbody></table></div><p class="rule-note">比較同一留出資料；F1 越高越好，平方誤差越低越好。模型未超越基準的指標會照實呈現，不能據此宣稱已反推出藥理。</p>`}
 function excludedQueryFormula(){if(queryId!=='workbench')return queryId;const id=ctx.origin?.()?.id;return c.formulas.some(f=>f.id===id)?id:undefined}
 function run(){const model=getModel();lastQuery=queryId==='workbench'?{title:ctx.name(),selection:ctx.selection().map(x=>({...x})),sourceFormula:ctx.origin?.()||null,processingAndMass:ctx.processing?(()=>{const r=ctx.processing();return {version:r.version,basis:r.basis,massContext:ctx.massContext?.(),resolvedRows:r.resolvedRows,changes:r.changes,gramsComplete:r.gramsComplete,totalGrams:r.totalGrams,limitations:r.limitations,inputStatus:'實錄克數／炮製分支與工藝參數尚未用於此反推模型'}})():null}:F(queryId);prediction=I.predict(model,queryId==='workbench'?ctx.selection():{formulaId:queryId},{excludeFormulaId:excludedQueryFormula()});document.querySelector('#inference-results').innerHTML=qualityHTML(validation)+predictionHTML();document.querySelector('#export-inference').disabled=false;ctx.notify(prediction.abstained?'訓練支持不足，結果保留未知':'已完成文獻詞推估；可展開原方對照')}
 document.addEventListener('input',e=>{if(e.target.id==='formula-corpus-query'){q=e.target.value;page=0;document.querySelector('#formula-corpus-rows').innerHTML=rows()}if(e.target.id==='inference-element-search'){document.querySelector('#inference-element').innerHTML=elementOptions(e.target.value);elementId=document.querySelector('#inference-element').value;association=null;document.querySelector('#element-association-results').innerHTML='<p class="rule-note">請執行元素關聯分析。</p>'}});
 document.addEventListener('change',e=>{if(e.target.id==='formula-corpus-book'){book=e.target.value;page=0;document.querySelector('#formula-corpus-rows').innerHTML=rows()}if(e.target.id==='inference-query'){queryId=e.target.value;prediction=null;association=null;document.querySelector('#inference-results').innerHTML='<p class="empty-state">查詢已更新，請執行反推分析。</p>';document.querySelector('#element-association-results').innerHTML='<p class="rule-note">查詢方已變更，請重新分析以套用排除組。</p>';document.querySelector('#export-inference').disabled=true}if(e.target.id==='inference-element'){elementId=e.target.value;association=null;document.querySelector('#element-association-results').innerHTML='<p class="rule-note">元素已更新，請執行分析。</p>'}});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.formulaPage){page+=Number(b.dataset.formulaPage);document.querySelector('#formula-corpus-rows').innerHTML=rows()}if(b.dataset.formulaRecord){chosen=b.dataset.formulaRecord;document.querySelector('#formula-detail-container').innerHTML=detail();document.querySelector('#formula-record-detail').scrollIntoView({behavior:'smooth',block:'start'})}if(b.dataset.inferRecord){queryId=b.dataset.inferRecord;prediction=null;association=null;document.querySelector('[data-view="inference"]').click();run();window.scrollTo({top:0,behavior:'smooth'})}if(b.dataset.stageRecord)ctx.stageCorpus(F(b.dataset.stageRecord));if(b.dataset.exportRecord)download(F(b.dataset.exportRecord),'原方文獻記錄.json');if(b.id==='run-inference')run();if(b.id==='run-element-association'&&elementId){association=I.elementAssociations(getModel(),elementId,{excludeFormulaId:excludedQueryFormula()});document.querySelector('#element-association-results').innerHTML=associationHTML()}if(b.id==='run-inference-validation'){b.disabled=true;b.textContent='計算中…';setTimeout(()=>{try{validation=I.validate(getModel(),{folds:5});document.querySelector('#inference-validation-results').innerHTML=validationHTML();ctx.notify('已實際完成分組驗證，結果與詞頻基準並列')}finally{b.disabled=false;b.textContent='重新查看分組驗證'}},30)}if(b.id==='export-inference'&&prediction)download({createdAt:new Date().toISOString(),purpose:'配伍成分反推歷史主治原詞；非臨床藥效',query:lastQuery,prediction,association,validation,method:I.version,parameters:getModel().config,inputPolicy:getModel().inputPolicy,dictionaryVersion:I.dictionaryVersion,datasetVersion:c.version,contentRevision:c.contentRevision,datasetFingerprint:window.INFERENCE_VALIDATION?.dataset?.sha256,sources:[...d.sources,...c.sources],limitations:c.limitations},'方劑文獻藥性反推.json')});
 return {render,citation};
})();
